widget.draw:
function draw(ctx, state, t) {
  function fmt(v) { return Math.round(v * 100) / 100; }
  var w = state.w;
  var h = state.h;
  var beta = state.beta;
  var gap = state.gap;
  var e = Math.exp(gap / beta);
  var p = e / (1 + e);
  var q = 1 - p;
  var thr = gap / Math.log(9);
  var x0 = 60;
  var x1 = 580;
  var bmin = 0.2;
  var bmax = 3.0;
  var bx = x0 + (beta - bmin) / (bmax - bmin) * (x1 - x0);
  var tx = x0 + (thr - bmin) / (bmax - bmin) * (x1 - x0);
  var isClip = false;
  if (tx < x0) { tx = x0; isClip = true; }
  if (tx > x1) { tx = x1; isClip = true; }
  var baseY = 250;
  var maxH = 170;
  var hTop = p * maxH;
  var hLow = q * maxH;
  var bw = 110;
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = "#f6f3ec";
  ctx.fillRect(0, 0, w, h);
  ctx.font = "12px sans-serif";
  ctx.fillStyle = "#1d1a16";
  ctx.fillText("beta = " + fmt(beta), 60, 28);
  ctx.fillText("gap = " + fmt(gap), 220, 28);
  ctx.fillText("p_top = " + fmt(p), 380, 28);
  ctx.fillStyle = "#1f4b99";
  ctx.fillRect(90, baseY - hTop, bw, hTop);
  ctx.fillStyle = "#c4512c";
  ctx.fillRect(330, baseY - hLow, bw, hLow);
  ctx.fillStyle = "#1d1a16";
  ctx.fillText("top " + fmt(p), 90, baseY - hTop - 8);
  ctx.fillText("other " + fmt(q), 330, baseY - hLow - 8);
  ctx.fillText("top token", 90, baseY + 16);
  ctx.fillText("other token", 330, baseY + 16);
  ctx.strokeStyle = "#1d1a16";
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(90, baseY - maxH - 30);
  ctx.lineTo(90, baseY);
  ctx.moveTo(90, baseY);
  ctx.lineTo(470, baseY);
  ctx.stroke();
  ctx.fillStyle = "#1d1a16";
  ctx.fillText("0", 70, baseY + 4);
  ctx.fillText("1", 70, baseY - maxH + 4);
  var axY = 310;
  ctx.strokeStyle = "#1d1a16";
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(x0, axY);
  ctx.lineTo(x1, axY);
  ctx.stroke();
  ctx.fillStyle = "#1f4b99";
  ctx.fillRect(bx - 3, axY - 12, 6, 24);
  ctx.fillStyle = "#1d1a16";
  ctx.fillText("beta", bx - 12, axY + 36);
  ctx.strokeStyle = "#c4512c";
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(tx, axY - 16);
  ctx.lineTo(tx, axY + 16);
  ctx.stroke();
  ctx.fillStyle = "#c4512c";
  ctx.fillText("p_top 0.9 = " + fmt(thr), tx - 50, axY - 22);
  if (isClip) { ctx.fillStyle = "#c4512c"; ctx.fillText("clipped", tx - 20, axY + 36); }
}
